(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.045+t*0.5)*6 + Math.cos(y*0.035-t*0.4)*5;
  const w2y = Math.cos(y*0.04-t*0.45)*6 + Math.sin(x*0.038+t*0.55)*5;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*40, 0.11, 2.1, 0.9],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*50, 0.085, 1.8, 1.0]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += (Math.sin(d*f - t*sp) + Math.sin(d*f*1.5 - t*sp*1.3 + 0.8)*0.5) * w;
    iS += (Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) + Math.cos(d*f*1.2 + t*sp*0.9 - 1.0)*0.5) * w;
  }
  const act = aS/8, inh = iS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.07+t*1.5)*Math.cos(sy*0.06-t*1.2)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const cx2 = 240+Math.sin(t*0.3)*80, cy2 = 120+Math.cos(t*0.4)*60;
  const d2 = Math.sqrt((sx-cx2)**2 + (sy-cy2)**2), a2 = Math.atan2(sy-cy2, sx-cx2);
  const sp2 = (Math.sin(d2*0.06-a2*2.5-t*1.8) + Math.cos(d2*0.035+a2*5-t*0.9))*0.3;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + sp1 + sp2)*2.2);
  const cell1 = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2 = Math.tanh((Math.sin(sx*0.25+t*0.3)*Math.cos(sy*0.22-t*0.2))*1.2)*0.15;
  const dx = Math.sin((sx+1)*0.15)*Math.sin(sy*0.15) - Math.sin((sx-1)*0.15)*Math.sin(sy*0.15);
  const dy = Math.sin(sx*0.15)*Math.sin((sy+1)*0.15) - Math.sin(sx*0.15)*Math.sin((sy-1)*0.15);
  const edge = Math.min(1, Math.sqrt(dx*dx + dy*dy)*3);
  const blend = reaction*0.65 + (cell1+cell2)*0.25 + edge*0.1, v = blend*0.5+0.5;
  const pal = [[5,12,55],[12,50,90],[18,95,115],[30,150,130],[120,190,80],[220,195,50],[235,140,55],[210,90,60],[170,50,65],[110,25,55],[50,15,45],[5,12,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15, glow = Math.max(0, reaction)*0.3;
  const bright = lum*(Math.abs(reaction)>0.8?1.12:1.0)+glow;
  return [
    Math.min(255, Math.max(0, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*bright+glow*40))|0,
    Math.min(255, Math.max(0, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*bright+glow*30))|0,
    Math.min(255, Math.max(0, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*bright+glow*20))|0
  ];
}
